                centers.append((r, c))

    out = [row[:] for row in grid]

    # Link neighboring diamond centers that share a row or column.
    for r in range(h):
        cols = sorted(c for rr, c in centers if rr == r)
        for a, b in zip(cols, cols[1:]):
